import { BaseModel } from "../../baseModel.js";
/**
 * Attachment - a file linked to a channel (and optionally a message).
 * channel_id scopes the file for permission checks; message_id is null until
 * the file is attached to a posted message. storage_key is the StorageBackend
 * key; the row carries only metadata, never the blob.
 */
export default class Attachment extends BaseModel {
    static tableName: string;
    static fields: {
        id: {
            type: "integer";
            primaryKey: boolean;
            autoIncrement: boolean;
        };
        channel_id: {
            type: "integer";
        };
        message_id: {
            type: "integer";
        };
        storage_key: {
            type: "string";
            required: boolean;
            maxLength: number;
        };
        filename: {
            type: "string";
            maxLength: number;
        };
        mime: {
            type: "string";
            maxLength: number;
        };
        size: {
            type: "integer";
        };
        thumb_key: {
            type: "string";
            maxLength: number;
        };
    };
}
